def orfs(s, minaa=50):
    stops=set(['TAA','TAG','TGA'])
    res=[]
    for strand,s2 in (('+',s),('-',rc(s))):
        for f in range(3):
            i=f
            start=None
            while i+3<=len(s2):
                cod=s2[i:i+3]
                if cod=='ATG' and start is None:
