seq = ''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)
comp=str.maketrans('ACGT','TGCA')
def rc(s): return s.translate(comp)[::-1]
def translate(s):
    tab={}; bases='TCAG'; aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
    k=0
    for a in bases:
        for b in bases:
            for c in bases:
                tab[a+b+c]=aas[k]; k+=1
    return ''.join(tab.get(s[j:j+3],'X') for j in range(0,len(s)-2,3))

def find_orfs(s, strand, minaa=90):
    stops={'TAA','TAG','TGA'}; out=[]
    for f in range(3):
        i=f; start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod=='ATG' and start is None: start=i
            if cod in stops:
                if start is not None:
                    aa=(i-start)//3
                    if aa>=minaa: out.append((strand,f,start,i+3,aa))
                start=None
            i+=3
    return out

